<?php

declare(strict_types=1);

/**
 * OneShot Framework Core local builder.
 * Run from the repository root:
 *   php build-oneshot.php
 */

$root = __DIR__;
$payload = '';
$json = gzuncompress(base64_decode($payload, true));
if ($json === false) {
    fwrite(STDERR, "Unable to decode embedded framework payload." . PHP_EOL);
    exit(1);
}
$files = json_decode($json, true, 512, JSON_THROW_ON_ERROR);

foreach ($files as $path => $contents) {
    $target = $root . DIRECTORY_SEPARATOR . str_replace('/', DIRECTORY_SEPARATOR, $path);
    $dir = dirname($target);
    if (!is_dir($dir)) {
        mkdir($dir, 0775, true);
    }
    file_put_contents($target, $contents);
    echo "wrote {$path}" . PHP_EOL;
}

if (!is_file($root . '/.env') && is_file($root . '/.env.example')) {
    copy($root . '/.env.example', $root . '/.env');
    echo "created .env from .env.example" . PHP_EOL;
}

echo PHP_EOL . "OneShot Framework Core generated." . PHP_EOL;
echo "Next:" . PHP_EOL;
echo "  php mobo doctor" . PHP_EOL;
echo "  php mobo db:touch" . PHP_EOL;
echo "  php mobo migrate" . PHP_EOL;
echo "  php mobo user:create admin@example.com your-password Admin" . PHP_EOL;
